import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA source implementing RMSNorm for FP16 tensors
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cmath>

template <int BLOCK_SIZE>
__global__ void rms_norm_fp16_kernel(const __half* __restrict__ input,
                                     __half* __restrict__ output,
                                     const int batch,
                                     const int channels,
                                     const int inner,
                                     const float eps) {
    // each block processes one (batch, inner) element
    int idx = blockIdx.x;
    if (idx >= batch * inner) return;

    const int b = idx / inner;
    const int inner_idx = idx % inner;

    // stride between consecutive channel elements for the same (b, inner_idx)
    const int stride = inner;

    // accumulate sum of squares in FP32
    float sum = 0.0f;
    for (int c = threadIdx.x; c < channels; c += BLOCK_SIZE) {
        int pos = ((b * channels + c) * inner) + inner_idx; // contiguous layout (B,C,inner...)
        __half h = input[pos];
        float v = __half2float(h);
        sum += v * v;
    }

    // reduction in shared memory
    __shared__ float shmem[BLOCK_SIZE];
    shmem[threadIdx.x] = sum;
    __syncthreads();

    // parallel reduction (power of two BLOCK_SIZE assumed)
    #pragma unroll
    for (int stride_red = BLOCK_SIZE / 2; stride_red > 0; stride_red >>= 1) {
        if (threadIdx.x < stride_red) {
            shmem[threadIdx.x] += shmem[threadIdx.x + stride_red];
        }
        __syncthreads();
    }

    // RMS value (broadcast via shared memory)
    float rms = sqrtf(shmem[0] / static_cast<float>(channels) + eps);

    // write normalized output
    for (int c = threadIdx.x; c < channels; c += BLOCK_SIZE) {
        int pos = ((b * channels + c) * inner) + inner_idx;
        __half h = input[pos];
        float v = __half2float(h);
        float out = v / rms;
        output[pos] = __float2half(out);
    }
}

// launch wrapper
void rms_norm_fp16(torch::Tensor input, torch::Tensor output, float eps) {
    const int batch = input.size(0);
    const int channels = input.size(1);
    const int inner = input.numel() / (batch * channels); // product of remaining dims

    const dim3 block(256);                     // 256 threads per block (must be power of two)
    const dim3 grid(batch * inner);            // one block per (batch, inner) element

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "rms_norm_fp16_kernel", ([&] {
        rms_norm_fp16_kernel<256><<<grid, block>>>(
            reinterpret_cast<const __half*>(input.data_ptr()),
            reinterpret_cast<__half*>(output.data_ptr()),
            batch,
            channels,
            inner,
            eps);
    }));
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel error: ") + cudaGetErrorString(err));
    }
}
'''

# Compile the inline extension
rmsnorm_ext = load_inline(name='rmsnorm_ext',
                          cpp_sources='',
                          cuda_sources=cuda_source,
                          functions=['rms_norm_fp16'],
                          verbose=False)

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference RMSNorm model,
    using a custom CUDA kernel for FP16 tensors.
    """
    def __init__(self, num_features: int, eps: float = 1e-5):
        super().__init__()
        self.num_features = num_features
        self.eps = eps

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("ModelNew only supports CUDA tensors.")
        if x.dtype != torch.float16:
            raise RuntimeError("ModelNew expects float16 (half) tensors.")
        # ensure contiguous layout for simple indexing
        x = x.contiguous()
        out = torch.empty_like(x)
        rmsnorm_ext.rms_norm_fp16(x, out, float(self.eps))
        return out
